var a=[{title:`Előnyök`,text:`Minden kéz saját terhet visz, ami gyakorlatiassá teszi az egyoldalas munkát, és olyan fogásszögeket tesz lehetővé, amelyeket egy rögzített rúd nem. Az egykezes evezés vagy az egykezes nyomás megmutathatja az oldalaid közti kontrollkülönbségeket. A súlyzók gyakran jobban elférnek kis helyen, mint egy teljes rudas felállás, bár a súlyok közötti ugrások nagyok lehetnek, vagy a választék korlátozott.`},{title:`Válaszd ki a súlyt`,text:`Olyan párat vagy egyetlen súlyzót válassz, amellyel egyenletes mozgással eléred a célként kitűzött ismétlésszámot, és néhány ismétlésnyi tartalék marad. Kezdőként evezéshez, bicepszcsavaráshoz és nyomásokhoz különböző terhelésekre lehet szükséged. Ha a következő súly túl nehéz, előbb a könnyebbel adj hozzá ismétléseket, tartományt vagy kontrollt.`},{title:`Állj be biztonságosan`,text:`Fekvenyomáshoz ülj le úgy, hogy a súlyzókat biztonságosan tartod a combod közelében, dőlj hátra kontrolláltan, és a súlyokat dobás nélkül mozgasd a helyükre. Álló emeléseknél a súlyokat a lábaddal és a törzseddel stabil helyzetben vedd fel. Ne ejtsd le a súlyokat ott, ahol a lábadra pattanhatnak, megrongálhatják a padlót, vagy eltalálhatnak valakit.`},{title:`Gyakori felhasználások`,text:`A súlyzós kehelyguggolás és román felhúzás az alsótestet edzi, a támasztott evezések és nyomások a felsőtestet fedik le, a hordozások pedig fogóerőt és törzskontrollt építenek. Ha csak egy súlyzód van, egyoldalas mozdulatokra használd.`},{title:`A TrainUp használata`,text:`A Profilban add meg a birtokodban lévő súlyzók súlyát. A terved olyan gyakorlatokat választ, amelyek illenek a felszerelésedhez, a helyedhez és a belmagasságodhoz. Súlyokat nem ír elő, így te választod a terhelést. Ha az edzés után feljegyzed a terheléseidet, minden alkalommal ugyanúgy írd le, például „12 kg kézenként”.`}];var l=[{label:`Mayo Clinic: szabad súlyok és gépi súlyok összehasonlítása`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`ACE gyakorlatkönyvtár`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: súlyzós edzés technikája (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var s={sections:a,sources:l};export{s as default,a as sections,l as sources};